/**
 * Give out the checks of the values of the \p shape.
 */
const std::vector<Check>& ChecksOf(Shape shape) {
  switch (shape) {
    case Shape::kCode: {
      static const std::vector<Check> checks = {
        {
          &Code_0,
          L"Code must not be empty."
        }
      };
      return checks;
    }
    case Shape::kSomething: {
      static const std::vector<Check> checks = {
        {
          &Something_0,
          L"Texts must be counted at least once."
        },
        {
          &Something_1,
          L"Texts must be grouped by their lengths."
        },
        {
          &Something_2,
          L"Optional texts must not share any text with texts."
        },
        {
          &Something_3,
          L"Numbers but zero must repeat at most twice, and some must "
          L"not repeat."
        },
        {
          &Something_4,
          L"Numbers must be named."
        },
        {
          &Something_5,
          L"Kinds must weigh at most 5."
        },
        {
          &Something_6,
          L"Codes must be unique."
        },
        {
          &Something_7,
          L"Kinds must be unique."
        },
        {
          &Something_8,
          L"Texts must be unique."
        }
      };
      return checks;
    }
    case Shape::kRegistry: {
      static const std::vector<Check> checks = {
        {
          &Registry_0,
          L"Weights must sum up to at most 10."
        },
        {
          &Registry_1,
          L"Optional counts must not be empty, if specified."
        },
        {
          &Registry_2,
          L"Codes by name must be at most 5 characters long."
        },
        {
          &Registry_3,
          L"Kinds by code must not be gamma."
        },
        {
          &Registry_4,
          L"Labels must be short."
        },
        {
          &Registry_5,
          L"Items must be named by their keys."
        },
        {
          &Registry_6,
          L"There must be at most five counts by number."
        },
        {
          &Registry_7,
          L"Counts by number must be smaller than 3."
        }
      };
      return checks;
    }
    default:
      throw std::logic_error(
        common::Concat(
          "Unexpected shape: ",
          std::to_string(static_cast<std::uint32_t>(shape))
        )
      );
  }
}

